"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useState } from "react";
import { ArrowRight } from "react-feather";
import { Button, Flex, Input, Text, styled, useSporeColors } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useEarnContext } from "../../ContextProvider";
const Container = styled(Flex, {
  flexDirection: "column",
  gap: "$spacing16",
  width: "100%",
  maxWidth: 480,
  // Approximate width from screenshot
  "$platform-web": {
    position: "sticky",
    top: "110px"
  }
});
const TabContainer = styled(Flex, {
  flexDirection: "row",
  gap: "$spacing8",
  marginBottom: "$spacing8"
});
const TabButton = styled(Button, {
  backgroundColor: "transparent",
  borderRadius: "$roundedFull",
  paddingVertical: "$spacing8",
  paddingHorizontal: "$spacing16",
  borderWidth: 0,
  variants: {
    active: {
      true: {
        backgroundColor: "$surface3",
        color: "$neutral1"
      },
      false: {
        backgroundColor: "transparent",
        color: "$neutral2",
        hoverStyle: {
          backgroundColor: "$surface2"
        }
      }
    }
  }
});
const Card = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing8",
  position: "relative"
});
const InputField = styled(Input, {
  unstyled: true,
  backgroundColor: "transparent",
  borderWidth: 0,
  outlineStyle: "none",
  padding: 0,
  fontSize: "48px",
  // Large font per screenshot
  fontWeight: "400",
  color: "$neutral1",
  width: "100%",
  textAlign: "left",
  placeholderTextColor: "$neutral3",
  height: "auto",
  lineHeight: "56px"
});
const MaxButton = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$rounded8",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  cursor: "pointer",
  hoverStyle: { opacity: 0.8 }
});
const InfoRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing12"
});
const ActionButton = styled(Button, {
  width: "100%",
  borderRadius: "$rounded20",
  backgroundColor: "$accent1",
  py: "$spacing24",
  hoverStyle: {
    backgroundColor: "$accent1Hovered"
  },
  pressStyle: {
    backgroundColor: "$accent1Pressed"
  }
});
export default function DepositWithdraw({ vault }) {
  const [activeTab, setActiveTab] = useState("deposit");
  const [amount, setAmount] = useState("");
  const colors = useSporeColors();
  const { openTransaction } = useEarnContext();
  if (!vault) return null;
  const isDeposit = activeTab === "deposit";
  const title = isDeposit ? "Deposit" : "Withdraw";
  const tokenSymbol = vault.token.symbol;
  const apy = vault.apy;
  const currentBalance = isDeposit ? 8.85 : 0.01;
  const currentPosition = 0;
  const pricePerToken = 1;
  const parsedAmount = parseFloat(amount) || 0;
  const usdValue = parsedAmount * pricePerToken;
  const newPosition = isDeposit ? currentPosition + parsedAmount : Math.max(0, currentPosition - parsedAmount);
  const projectedMonthly = newPosition * (apy / 100) / 12;
  const projectedYearly = newPosition * (apy / 100);
  const currentMonthly = currentPosition * (apy / 100) / 12;
  const currentYearly = currentPosition * (apy / 100);
  const handleSubmit = () => {
    openTransaction(vault, activeTab, "review", amount);
  };
  return <Container>
      {
    /* Tabs */
  }
      <TabContainer>
        <TabButton active={activeTab === "deposit"} onPress={() => setActiveTab("deposit")}>
          <Text variant="buttonLabel2" color={activeTab === "deposit" ? "$neutral1" : "$neutral2"}>
            Deposit
          </Text>
        </TabButton>
        <TabButton active={activeTab === "withdraw"} onPress={() => setActiveTab("withdraw")}>
          <Text variant="buttonLabel2" color={activeTab === "withdraw" ? "$neutral1" : "$neutral2"}>
            Withdraw
          </Text>
        </TabButton>
      </TabContainer>

      {
    /* Input Card */
  }
      <Card>
        <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
          <Text variant="body2" color="$neutral2">
            {title} {tokenSymbol}
          </Text>
          {
    /* Token Logo Top Right */
  }
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name ?? ""}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={20}
  />
        </Flex>

        <InputField placeholder="0.00" value={amount} onChangeText={setAmount} placeholderTextColor="$neutral3" />

        <Flex flexDirection="row" justifyContent="space-between" alignItems="center" mt="$spacing4">
          <Text variant="body3" color="$neutral3">
            ${usdValue.toFixed(2)}
          </Text>
          <Flex flexDirection="row" gap="$gap8" alignItems="center">
            <Text variant="body3" color="$neutral2">
              {currentBalance < 0.01 ? "< 0.01" : currentBalance.toFixed(2)} {tokenSymbol}
            </Text>
            <MaxButton onPress={() => setAmount(currentBalance.toString())}>
              <Text variant="buttonLabel4" color="$neutral2">
                MAX
              </Text>
            </MaxButton>
          </Flex>
        </Flex>
      </Card>

      {
    /* Info Card */
  }
      <Card>
        {
    /* Deposit/Withdraw Row */
  }
        <InfoRow>
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name ?? ""}
    images={[getTokenLogoUrl(vault.token.id)]}
    size={20}
  />
            <Text variant="body2" color="$neutral2">
              {title} ({tokenSymbol})
            </Text>
          </Flex>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <Text variant="body2" color="$neutral2">
              {currentPosition < 0.01 ? "< 0.01" : currentPosition.toFixed(2)}
            </Text>
            <ArrowRight size={14} color={colors.neutral3.val} />
            <Text variant="body2" color="$neutral1">
              {newPosition.toFixed(2)}
            </Text>
          </Flex>
        </InfoRow>

        {
    /* APY Row */
  }
        <InfoRow>
          <Text variant="body2" color="$neutral2">
            APY
          </Text>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            {
    /* Sparkles icon placeholder or from a library if available */
  }
            <Text variant="body2" color="$accent1">
              ✦
            </Text>
            <Text variant="body2" color="$neutral1">
              {apy.toFixed(2)}%
            </Text>
          </Flex>
        </InfoRow>

        {
    /* Monthly Earnings Row */
  }
        <InfoRow>
          <Text variant="body2" color="$neutral2">
            Projected monthly earnings
          </Text>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <Text variant="body2" color="$neutral2">
              ${currentMonthly < 0.01 ? "< 0.01" : currentMonthly.toFixed(2)}
            </Text>
            <ArrowRight size={14} color={colors.neutral3.val} />
            <Text variant="body2" color="$neutral1">
              ${projectedMonthly < 0.01 && projectedMonthly > 0 ? "< 0.01" : projectedMonthly.toFixed(2)}
            </Text>
          </Flex>
        </InfoRow>

        {
    /* Yearly Earnings Row */
  }
        <InfoRow style={{ marginBottom: 0 }}>
          <Text variant="body2" color="$neutral2">
            Projected yearly earnings
          </Text>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <Text variant="body2" color="$neutral2">
              ${currentYearly < 0.01 ? "< 0.01" : currentYearly.toFixed(2)}
            </Text>
            <ArrowRight size={14} color={colors.neutral3.val} />
            <Text variant="body2" color="$neutral1">
              ${projectedYearly < 0.01 && projectedYearly > 0 ? "< 0.01" : projectedYearly.toFixed(2)}
            </Text>
          </Flex>
        </InfoRow>
      </Card>

      {
    /* Action Button */
  }
      <ActionButton onPress={handleSubmit}>{title}</ActionButton>
    </Container>;
}
